use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur: int = self.root
        while cur >= 0 {
            let k: int = self.keys[cur]
            if x == k {
                return true
            }
            if x < k {
                cur = self.left[cur]
            } else {
                cur = self.right[cur]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.contains(x) {
            return false
        }
        let id: int = self.keys.len() as int
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root < 0 {
            self.root = id
            return true
        }
        let mut cur: int = self.root
        let mut going = true
        while going {
            if x < self.keys[cur] {
                if self.left[cur] < 0 {
                    self.left[cur] = id
                    going = false
                } else {
                    cur = self.left[cur]
                }
            } else {
                if self.right[cur] < 0 {
                    self.right[cur] = id
                    going = false
                } else {
                    cur = self.right[cur]
                }
            }
        }
        true
    }

    fn replace_child(self, parent: int, old: int, new: int) {
        if parent < 0 {
            self.root = new
        } else if self.left[parent] == old {
            self.left[parent] = new
        } else {
            self.right[parent] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent: int = -1
        let mut cur: int = self.root
        while cur >= 0 && self.keys[cur] != x {
            parent = cur
            if x < self.keys[cur] {
                cur = self.left[cur]
            } else {
                cur = self.right[cur]
            }
        }
        if cur < 0 {
            return false
        }
        let l: int = self.left[cur]
        let r: int = self.right[cur]
        if l >= 0 && r >= 0 {
            let mut sp: int = cur
            let mut s: int = r
            while self.left[s] >= 0 {
                sp = s
                s = self.left[s]
            }
            self.keys[cur] = self.keys[s]
            let sr: int = self.right[s]
            self.replace_child(sp, s, sr)
        } else if l >= 0 {
            self.replace_child(parent, cur, l)
        } else {
            self.replace_child(parent, cur, r)
        }
        true
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur: int = self.root
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.left[cur]
            }
            let n: int = stack.pop().unwrap_or(-1)
            out.push("${self.keys[n]}")
            cur = self.right[n]
        }
        if out.len() == 0 {
            return "<empty>"
        }
        out.join(" ")
    }

    fn height(self) -> int {
        if self.root < 0 {
            return 0
        }
        let mut level: Vec<int> = [self.root]
        let mut h: int = 0
        while level.len() > 0 {
            h += 1
            let mut next: Vec<int> = []
            for n in level {
                if self.left[n] >= 0 {
                    next.push(self.left[n])
                }
                if self.right[n] >= 0 {
                    next.push(self.right[n])
                }
            }
            level = next
        }
        h
    }

    fn min(self) -> string {
        if self.root < 0 {
            return "empty"
        }
        let mut cur: int = self.root
        while self.left[cur] >= 0 {
            cur = self.left[cur]
        }
        "${self.keys[cur]}"
    }

    fn max(self) -> string {
        if self.root < 0 {
            return "empty"
        }
        let mut cur: int = self.root
        while self.right[cur] >= 0 {
            cur = self.right[cur]
        }
        "${self.keys[cur]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").map(|s| s.to_string()).collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height()}")
        } else if cmd == "min" {
            println(t.min())
        } else if cmd == "max" {
            println(t.max())
        }
    }
}

